// Weryfikacja podpisu żądania z kalkulatora (HMAC-SHA256) i deduplikacja po X-Event-Id.
// Wymaga w n8n: zmiennej środowiskowej ATAI_WEBHOOK_SECRET (ten sam sekret co N8N_WEBHOOK_SECRET w Supabase)
// oraz NODE_FUNCTION_ALLOW_BUILTIN=crypto (dostęp do modułu crypto w węźle Code).
const crypto = require('crypto');
const { headers, body } = $input.first().json;
const secret = $env.ATAI_WEBHOOK_SECRET;
const reject = (reason, status) => [{ json: { send: false, status, reason } }];

if (!secret) return reject('brak_sekretu_w_n8n', 500);

const timestamp = String(headers['x-timestamp'] || '');
if (!/^[0-9]{1,12}$/.test(timestamp)) return reject('zly_znacznik_czasu', 401);
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return reject('przeterminowane', 401);

// Treść podpisana po stronie kalkulatora to JSON.stringify(payload); parsowanie i ponowna serializacja daje ten sam tekst.
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + JSON.stringify(body)).digest('hex');
const given = Buffer.from(String(headers['x-signature'] || ''));
const wanted = Buffer.from(expected);
if (given.length !== wanted.length || !crypto.timingSafeEqual(given, wanted)) return reject('zly_podpis', 401);

// Dostarczanie jest „co najmniej raz”: ten sam alert może przyjść dwa razy (X-Event-Id jest taki sam).
const eventId = String(headers['x-event-id'] || body.eventId || '');
const store = $getWorkflowStaticData('global');
const seen = Array.isArray(store.seen) ? store.seen : [];
if (eventId && seen.includes(eventId)) return [{ json: { send: false, status: 200, reason: 'duplikat' } }];
store.seen = [...seen, eventId].slice(-500);

return [{ json: { send: true, status: 200, chatId: body.channel.target, text: body.message + '\n' + body.sessionUrl } }];
